import {clock24,clock12,weekday,daysInMonth} from './b32-model.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(a,label,i,pressed=false)=>`<button type="button" data-x="t32-${a}"${i===undefined?'':` data-index="${esc(i)}"`} aria-pressed="${!!pressed}">${esc(label)}</button>`;
const svg=(s,label,h=300)=>`<svg viewBox="0 0 760 ${h}" role="img" aria-label="${esc(label)}">${s}</svg>`;
const input=(k,label,v,placeholder='')=>`<label class="t32-field">${esc(label)}<input data-xfield="${esc(k)}" value="${esc(v)}" placeholder="${esc(placeholder)}" autocomplete="off"></label>`;
const select=(k,label,v,options)=>`<label class="t32-field">${esc(label)}<select data-xfield="${esc(k)}"><option value="">选择</option>${options.map(([a,b])=>`<option value="${esc(a)}" ${String(v)===String(a)?'selected':''}>${esc(b)}</option>`).join('')}</select></label>`;
const roman=['XII','I','II','III','IV','V','VI','VII','VIII','IX','X','XI'];
function clock(t,b){const cx=255,cy=150,R=115,p=(angle,len)=>[cx+Math.sin(angle)*len,cy-Math.cos(angle)*len];let s=`<circle cx="${cx}" cy="${cy}" r="${R}" fill="#fffdf4" stroke="#789681" stroke-width="3"/>`;
 for(let i=0;i<60;i++){const a=i*Math.PI/30,[x,y]=p(a,R-3),[x2,y2]=p(a,R-(i%5===0?15:9));s+=`<line x1="${x}" y1="${y}" x2="${x2}" y2="${y2}" stroke="#6d8b78" stroke-width="${i%5===0?2:1}"/>`;}
 for(let i=0;i<12;i++){const a=i*Math.PI/6,[x,y]=p(a,R-31),n=t.roman?(i===4&&t.romanFour?'IIII':roman[i]):i||12;s+=`<text x="${x}" y="${y+5}" text-anchor="middle" font-size="${t.roman?15:18}">${n}</text>`;if(t.mode==='set'){const[xx,yy]=p(a,R);s+=`<circle cx="${xx}" cy="${yy}" r="11" fill="transparent" role="button" tabindex="0" data-x="t32-minute" data-index="${i*5}" aria-label="长针指向第 ${i||12} 个位置"/>`;}}
 const H=(b.hour+b.minute/60)*Math.PI/6,M=b.minute*Math.PI/30,[hx,hy]=p(H,61),[mx,my]=p(M,91);s+=`<line x1="${cx}" y1="${cy}" x2="${hx}" y2="${hy}" stroke="#345e50" stroke-width="8" stroke-linecap="round"/><line x1="${cx}" y1="${cy}" x2="${mx}" y2="${my}" stroke="#cb7653" stroke-width="5" stroke-linecap="round"/><circle cx="${cx}" cy="${cy}" r="7" fill="#385c4d"/><text x="485" y="105">短针：小时</text><text x="485" y="140">长针：分钟</text>`;
 if(t.given)s+=`<text x="485" y="195">${esc(t.given)}</text>`;return svg(s,'可观察的钟面；长针表示分钟，短针随之移动');}
function romanFace(t,b){const cx=380,cy=150,R=112;let s=`<circle cx="${cx}" cy="${cy}" r="${R}" fill="#fffdf4" stroke="#789681" stroke-width="3"/>`;for(let i=0;i<12;i++){const a=i*Math.PI/6,x=cx+Math.sin(a)*85,y=cy-Math.cos(a)*85;s+=`<circle cx="${x}" cy="${y}" r="20" fill="${b.placed[i]===null?'#edf2e8':'#a8cfb7'}" stroke="#6a8d78" data-x="t32-place" data-index="${i}" role="button" tabindex="0" aria-label="钟面第 ${i||12} 个位置"/><text x="${x}" y="${y+5}" text-anchor="middle" pointer-events="none">${b.placed[i]===null?'？':roman[b.placed[i]]}</text>`;}return svg(s,'把罗马数字放到钟面的十二个位置');}
function compare(t,b){if(!b.revealed)return svg('<text x="380" y="135" text-anchor="middle">先猜一猜，再展开两段时间</text>','预测后显示两段时间',230);const lo=Math.min(...t.events.map(x=>x.start)),hi=Math.max(...t.events.map(x=>x.end)),scale=500/(hi-lo||1);let s=`<line x1="130" y1="245" x2="630" y2="245" stroke="#72917c" stroke-width="2"/>`;t.events.forEach((e,i)=>{let x=130+(e.start-lo)*scale,w=(e.end-e.start)*scale,y=50+i*85;s+=`<text x="15" y="${y+25}">${esc(e.name)}</text><rect x="${x}" y="${y}" width="${w}" height="38" rx="8" fill="${i?'#deb88c':'#9cc9b1'}"/><text x="${x}" y="${y+60}">开始</text><text x="${x+w}" y="${y+60}" text-anchor="end">结束</text>`;});return svg(s,'同一时间轴上对比两个活动的开始和结束',290);}
function parts(t,b){if(t.shape==='clock'){const cx=380,cy=150,r=110;let s=`<text x="380" y="20" text-anchor="middle">整个一圈：${t.total} ${esc(t.unit)}</text>`;for(let i=0;i<t.parts;i++){const a=i*2*Math.PI/t.parts-Math.PI/2,z=(i+1)*2*Math.PI/t.parts-Math.PI/2,x=cx+r*Math.cos(a),y=cy+r*Math.sin(a),X=cx+r*Math.cos(z),Y=cy+r*Math.sin(z);s+=`<path d="M${cx} ${cy} L${x} ${y} A${r} ${r} 0 ${t.parts===2?0:0} 1 ${X} ${Y} Z" fill="${b.selected.includes(i)?'#8ec4ac':'#edf2e8'}" stroke="#688a77" stroke-width="2" data-x="t32-part" data-index="${i}" role="button" tabindex="0" aria-label="选择钟面第 ${i+1} 份"/>`;}return svg(s,'钟面一圈平均分成相同的份',290);}const left=55,width=650/t.parts,y=75;let s=`<text x="55" y="35">整个活动：${t.total} ${esc(t.unit)}（时间从左到右）</text>`;for(let i=0;i<t.parts;i++)s+=`<rect x="${left+i*width}" y="${y}" width="${width}" height="70" fill="${b.selected.includes(i)?'#8ec4ac':'#edf2e8'}" stroke="#688a77" stroke-width="2" data-x="t32-part" data-index="${i}" role="button" tabindex="0" aria-label="选择第 ${i+1} 份"/>`;return svg(s,'一整段时间从左到右分成大小相同的份',185);}
function stopwatch(t,b){const val=`${String(Math.floor(b.elapsed/60)).padStart(2,'0')}:${String(b.elapsed%60).padStart(2,'0')}`,width=420*b.elapsed/t.duration;return svg(`<circle cx="220" cy="135" r="82" fill="#fffdf4" stroke="#729481" stroke-width="4"/><rect x="190" y="37" width="60" height="15" rx="5" fill="#729481"/><text x="220" y="145" text-anchor="middle" font-size="30">${val}</text><text x="220" y="175" text-anchor="middle">分 : 秒</text><text x="355" y="100">模拟活动</text><rect x="355" y="120" width="300" height="30" rx="8" fill="#e4ebe0"/><rect x="355" y="120" width="${width*300/420}" height="30" rx="8" fill="#8fc5aa"/><text x="355" y="185">${b.elapsed===t.duration?'活动结束':b.running?'活动进行中':b.elapsed?'计时暂时停下':'还没开始'}</text>`,'模拟活动与同步走动的秒表',250);}
function calendar(t,b){const [y,mo]=t.months[b.page],first=weekday(`${y}-${String(mo).padStart(2,'0')}-01`),offset=(first+6)%7,days=daysInMonth(y,mo);let cells=Array.from({length:offset},()=>'<span></span>');for(let d=1;d<=days;d++){const date=`${y}-${String(mo).padStart(2,'0')}-${String(d).padStart(2,'0')}`;cells.push(btn('day',String(d),date,b.selected.includes(date)));}return `<div class="t32-calendar"><div class="t32-month">${y} 年 ${mo} 月</div><div class="t32-cal-grid">${['一','二','三','四','五','六','日'].map(x=>`<strong>周${x}</strong>`).join('')}${cells.join('')}</div></div>`;}
function steps(t,b){const total=b.moves.reduce((a,x)=>a+x,0),n=t.start+total,end=t.unit==='秒'?`${Math.floor(n/60)} 分 ${n%60} 秒`:clock24(n),start=t.unit==='秒'?`${Math.floor(t.start/60)} 分 ${t.start%60} 秒`:clock24(t.start);return svg(`<line x1="85" y1="155" x2="675" y2="155" stroke="#70907a" stroke-width="3"/><circle cx="85" cy="155" r="7" fill="#56846c"/><circle cx="${85+590*total/t.duration}" cy="155" r="9" fill="#c57852"/><text x="85" y="120">从 ${esc(start)} 开始</text><text x="85" y="205">${b.moves.map(x=>'＋'+x+' '+t.unit).join('　')||'每次走一段'}</text><text x="85" y="250">现在：${esc(end)}</text>`,'从起点沿时间轴逐段前进',290);}
function orderVisual(t,b){return `<div class="t32-order-display">${Array.from({length:t.items.length},(_,i)=>`<span>${b.order[i]===undefined?'？':esc(t.items[b.order[i]].label)}</span>`).join('<b>→</b>')}</div>`;}
function units(t,b){return `<div class="t32-units">${t.parts.map((p,i)=>btn('unit',p.label,i,b.selected.includes(i))).join('')}</div>`;}
export function visual(t,m){const b=m.board,v=t.type==='x-t32-clock'?clock(t,b):t.type==='x-t32-roman'?romanFace(t,b):t.type==='x-t32-compare'?compare(t,b):t.type==='x-t32-parts'?parts(t,b):t.type==='x-t32-calendar'?calendar(t,b):t.type==='x-t32-stopwatch'?stopwatch(t,b):t.type==='x-t32-steps'?steps(t,b):t.type==='x-t32-units'?units(t,b):t.type==='x-t32-order'?orderVisual(t,b):'';return `<div class="t32-world">${v}</div>`;}
export function controls(t,m){const b=m.board;let s='<div class="t32-controls">';
 if(t.type==='x-t32-clock'&&t.mode==='set'){s+=select('hour','先选短针经过的小时',m.hour,Array.from({length:12},(_,i)=>[String(i+1),String(i+1)]))+`<label class="t32-field"><span>移动长针：<output data-xvalue="minute">${esc(m.minute)}</output> 分</span><input type="range" min="0" max="59" step="1" data-xfield="minute" value="${esc(m.minute)}"></label><p>也可以点钟面外圈的五分钟位置。</p>`;}
 if(t.type==='x-t32-roman')s+=`<p>先选一个数字，再点钟面上的位置。</p><div class="t32-buttons">${roman.map((n,i)=>btn('pick',n,i,b.pick===i)).join('')}</div>`+btn('clear','重新摆');
 if(t.type==='x-t32-order')s+=`<p>按要求依次选择：</p><div class="t32-buttons">${t.items.map((x,i)=>btn('order',x.label,i,b.order.includes(i))).join('')}</div><p>目前顺序：${b.order.map(i=>esc(t.items[i].label)).join(' → ')}</p>${btn('clear','重新排列')}`;
 if(t.type==='x-t32-compare'){if(b.guess===null)s+='<p>先猜一猜：</p><div class="t32-buttons">'+[['left',t.events[0].name],['right',t.events[1].name],['equal','一样']].map(([v,l])=>btn('guess',l,v)).join('')+'</div>';else if(!b.revealed)s+=btn('reveal','展开时间');else s+='<p>现在怎样？</p><div class="t32-buttons">'+[['left',t.events[0].name],['right',t.events[1].name],['equal','一样']].map(([v,l])=>btn('choice',l,v,b.choice===v)).join('')+'</div>';}
 if(t.type==='x-t32-parts')s+=`<p>点选需要的等份，已选 ${b.selected.length} 份。</p>`;
 if(t.type==='x-t32-calendar')s+=(t.months.length>1?`<div class="t32-buttons">${t.months.map(([y,mo],i)=>btn('page',`${y} 年 ${mo} 月`,i,b.page===i)).join('')}</div>`:'')+`<p>已选：${b.selected.map(esc).join('、')||'还没选日期'}</p>`;
 if(t.type==='x-t32-stopwatch')s+=`<div class="t32-buttons">${btn('start','开始计时')}${btn('tick','前进10秒',10)}${btn('tick','前进30秒',30)}${btn('stop','停止计时')}</div>`;
 if(t.type==='x-t32-steps')s+=input('jump','这次走多少'+t.unit,m.jump)+btn('move','走这一段')+btn('undo','退回一步')+btn('clear','重新走');
 if(t.type==='x-t32-units')s+='<p>把每一份点进来，再记录结果。</p>';
 const ready=t.type!=='x-t32-compare'||b.revealed;
 if(ready)for(const [i,q]of(t.questions||[]).entries())s+=q.options?select('answers.'+i,q.label,m.answers[i],q.options):input('answers.'+i,q.label,m.answers[i],q.kind==='time12'||q.kind==='time24'?'例如 7:05':'');
 if(m.issue)s+=`<p class="t32-issue" role="status">${esc(m.issue)}</p>`;return s+`<details><summary>留下自己的想法（可选）</summary>${input('prose','我的解释或新问题',m.prose)}<small>原话会保存，暂不自动判断。</small></details></div>`;
}
export const render=(t,m)=>`<div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}</div>`;
